def solve(n, s):
    target = s[:n]
    if s[n:] == target:
        return ([], list(range(1, n + 1)))
    count = Counter(s)
    if count['0'] % 2 != 0 or count['1'] % 2 != 0:
        return -1
    target_count = Counter(target)
    for i in range(1, 2 * n):
        rotated_s = s[i:] + s[:i]
        if rotated_s[:n] == rotated_s[n:]:
            return ([], list(range(i + 1, i + n + 1)))
        if Counter(rotated_s[:n]) == target_count:
            b = [j + 1 for j in range(2 * n) if rotated_s[j] != s[j]]
            p = [j + 1 for j in range(n) if rotated_s[j] == target[j]]
            return (sorted(b), sorted(p))
    return -1

